# פרק 2 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=2
TITLE='המשפט הישראלי ומקורותיו'
SUM=[' <p>המשפט הישראלי הוא <strong>שיטה מעורבת</strong> שצמחה על רקע היסטורי ייחודי: משפט עות\'מאני, חקיקה מנדטורית בריטית, ועליהם המשפט הישראלי העצמאי שנבנה מאז 1948.</p> <h3>2.1 היררכיית מקורות המשפט</h3> <p><strong>חוקי היסוד</strong> — מעמד חוקתי-על מאז "המהפכה החוקתית"; <strong>חקיקה ראשית</strong> — חוקי הכנסת; <strong>חקיקת משנה</strong> — תקנות וצווים שמתקינה הרשות המבצעת מכוח הסמכה בחוק; <strong>תקדים שיפוטי</strong> — הלכת בית המשפט העליון; ו<strong>מנהג ועקרונות יסוד</strong>.</p> <h3>2.2 התקדים המחייב — סעיף 20</h3> <p>לפי <strong>סעיף 20 לחוק יסוד: השפיטה</strong>, הלכה שנפסקה בבית המשפט העליון <strong>מחייבת כל ערכאה נמוכה</strong> ממנו — אך העליון עצמו אינו כבול להלכותיו.</p> <h3>2.3 נקודות מפתח למבחן</h3> <ul><li>שיטה מעורבת — שכבות עות\'מאני/מנדט/ישראלי.</li><li>היררכיה: חוקי יסוד → חקיקה ראשית → משנה → תקדים → מנהג.</li><li>תקדים מחייב כלפי מטה (ס׳ 20).</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[('ע"א 6821/93 בנק המזרחי המאוחד נ\' מגדל כפר שיתופי', '', 'פסק הדin המכונן של "המהפכה החוקתית". נקבע כי חוקי היסוד הם בעלי מעמד נורמטיבי עליון, וכי לבית המשפט סמכות לבקר חקיקה רגילה הסותרת חוק יסוד. אבן יסוד להבנת היררכיית המקורות.'), ('בג״ץ 73/53 חברת ״קול העם״ בע״מ נ׳ שר הפנים', 'שר הפנים הורה על סגירה זמנית של העיתונים ״קול העם״ ו״אל־איתיחאד״ בשל מאמרי ביקורת על הממשלה, מכוח סמכות בפקודת העיתונות המנדטורית.', 'העתירה התקבלה. השופט אגרנט קבע שהכרזת העצמאות אמנם אינה חוקה, אך היא מבטאת את חזון העם ויש להתחשב בה בפירוש חוקי המדינה, ובכלל זה חקיקה מנדטורית שנקלטה. מכאן נגזרה הגנה על חופש הביטוי ונקבע מבחן ״הוודאות הקרובה״ לפגיעה באינטרס הציבורי. פסק הדין מדגים כיצד חיקוק מנדטורי שנקלט מכוח ס׳ 11 מתפרש לאור ערכי המדינה החדשה.'), ('ד״נ 13/80 הנדלס נ׳ בנק קופת עם בע״מ', 'אדם מצא על רצפת חדר הכספות של בנק מעטפה עם איגרות חוב שבעליהן לא אותרו. נחלקו הדעות אם המציאה שייכת למוצא או לבנק, לפי פירוש המונח ״רשותו של אדם אחר״ בחוק השבת אבידה.', 'בדיון הנוסף אושרה ברוב דעות ההכרעה לטובת הבנק. חשיבותו העיקרית של פסק הדין היא במחלוקת המתודולוגית: השופט אלון ראה במשפט העברי ״מקור השראה ראשי וראשון במעלה״ גם בפירוש מונחים, ואילו השופטים ברק, כהן ולנדוי קבעו שאין להעמיד את המשפט העברי כמקור פרשני מחייב, ושהפנייה לפי חוק יסודות המשפט שמורה ללאקונה אמיתית לאחר חקיקה, הלכה והיקש.'), ('ד״נ 40/80 קניג נ׳ כהן', 'דיון נוסף שבו שבו ונחלקו השופטים אלון וברק בשאלת מקומו של המשפט העברי בפרשנות חוקים ישראליים.', 'השופט אלון ביקש להרחיב את המקרים שבהם חובה לפנות למשפט העברי, ואף ראה בביטול סימן 46 הוראה שמחייבת פנייה אליו. השופט ברק קבע שהמשפט העברי ראוי לשמש מקור להשראה פרשנית, במיוחד כשהחוק נחקק בהשראתו, אך ההכרעה בין אפשרויות הפרשנות נשארת של בית המשפט, בלא בכורה מחייבת לשיטה אחרת.'), ('בג״ץ 1635/90 ז׳רז׳בסקי נ׳ ראש הממשלה', 'עתירה שעסקה בהסכם קואליציוני שנוי במחלוקת ובשאלת הביקורת השיפוטית על הסכמים פוליטיים.', 'לצד הדיון בביקורת השיפוטית על הסכמים פוליטיים, חזרה מחלוקת אלון–ברק. השופט ברק קבע שעקרונות החירות, הצדק, היושר והשלום של מורשת ישראל הם חלק מעקרונות היסוד של השיטה, אך אינם המקור היחיד שאליו יש לפנות. הגישה מבטאת את הקו שהשתרש בפסיקה: מקור חשוב, לא מקור בלעדי.')]
QS=[{'q': 'מה ההבדל בין ״מקור פורמלי״ ל״מקור היסטורי״ של נורמה משפטית?', 'o': ['מקור פורמלי הוא רק חוק יסוד; מקור היסטורי הוא כל השאר', 'מקור היסטורי גובר תמיד על מקור פורמלי', 'המקור הפורמלי הוא מה שנותן לנורמה תוקף מחייב; המקור ההיסטורי הוא מאיפה נלקח תוכנה', 'אין הבדל, אלה שמות נרדפים'], 'c': 2, 'e': 'נכון. חוק ישראלי יכול לשאוב רעיון מהמשפט הגרמני (מקור היסטורי), אך תוקפו נובע מחקיקת הכנסת (מקור פורמלי).'}, {'q': 'לפי סימן 46 לדבר המלך במועצה, מתי פנו בתי המשפט למשפט המקובל ולדיני היושר האנגליים?', 'o': ['רק בענייני מעמד אישי', 'תמיד, לפני כל חקיקה', 'רק כשהצדדים הסכימו לכך', 'רק כשהחקיקה העות׳מאנית והמנדטורית לא הסדירה את העניין, ובכפוף לתנאי המקום'], 'c': 3, 'e': 'נכון. המשפט האנגלי שימש ״צינור״ להשלמת חסר, ורק במידה שתנאי הארץ ותושביה התירו.'}, {'q': 'מה קובע ס׳ 11 לפקודת סדרי השלטון והמשפט?', 'o': ['שהמשפט העברי מחליף את המשפט המנדטורי', 'שכל החקיקה המנדטורית בטלה מיום הקמת המדינה', 'שבתי המשפט רשאים לבחור איזה דין להחיל', 'שהמשפט שהיה קיים ב־14 במאי 1948 ממשיך לעמוד בתוקפו, בכפוף לאי־סתירה לחקיקה החדשה ולשינויים הנובעים מהקמת המדינה'], 'c': 3, 'e': 'נכון. זה עיקרון הרציפות עם שני סייגיו.'}, {'q': 'בשנת 1965 התעוררה שאלה שלא הוסדרה בחקיקה הישראלית או המנדטורית. לפי איזה מסלול היה בית המשפט עשוי להיעזר במשפט האנגלי?', 'o': ['סימן 46, שהמשיך לחול מכוח ס׳ 11 לפקודת סדרי השלטון והמשפט', 'חוק יסודות המשפט', 'ס׳ 1 לחוק הפרשנות', 'לא היה שום מסלול כזה אחרי 1948'], 'c': 0, 'e': 'נכון. סימן 46 נקלט עם שאר המשפט הקיים ובוטל רק ב־1980.'}, {'q': 'מה קבע ס׳ 13 לפקודת סדרי השלטון והמשפט?', 'o': ['ביטל את סימן 46', 'הקים את בית המשפט העליון', 'החיל את המשפט העברי בענייני ממונות', 'ביטל את חקיקת הספר הלבן של 1939 והכיר בכל יהודי שעלה בניגוד לחוקי המנדט כעולה חוקי למפרע'], 'c': 3, 'e': 'נכון. ס׳ 13 ביטל את הגבלות העלייה ורכישת הקרקעות של הספר הלבן.'}, {'q': 'מה קבע ס׳ 15(ג) לפקודת סדרי השלטון והמשפט (כפי שתוקן ב־1972)?', 'o': ['שהוראה בחוק המחייבת לפרש אותו לפי דיני אנגליה או עיקרי הפרשנות האנגליים אינה עוד מחייבת', 'שהשפה האנגלית היא שפה רשמית', 'שפסיקה אנגלית חדשה מחייבת את בתי המשפט', 'שהמשפט האנגלי הוא מקור מחייב לפרשנות'], 'c': 0, 'e': 'נכון. זה צעד מרכזי בניתוק הפרשנות הישראלית מהמשפט האנגלי.'}, {'q': 'בית משפט מתבקש היום להחיל הלכה אנגלית משנת 1995 כמחייבת. מה הדין?', 'o': ['היא מחייבת רק את בתי משפט השלום', 'היא מחייבת מכוח ס׳ 11', 'היא מחייבת מכוח סימן 46', 'היא אינה מחייבת; לפסיקה אנגלית שאחרי הקמת המדינה אין כוח מחייב, וממילא סימן 46 בוטל — היא יכולה לשמש לכל היותר השראה'], 'c': 3, 'e': 'נכון. זו ההלכה שנקבעה כבר בשנות ה־50 (כוכבי נ׳ בקר), ומאז ביטול סימן 46 אין כל צינור לקליטה; משפט זר הוא משפט משווה בלבד.'}, {'q': 'מה קובע ס׳ 1 לחוק יסודות המשפט בנוסחו הנוכחי?', 'o': ['שבמקרה של לאקונה יש לפנות למשפט המקובל האנגלי', 'שהמשפט העברי גובר על חוקי הכנסת', 'שבכל ספק פרשני יש לפסוק לפי ההלכה', 'שבמקרה של לאקונה, אחרי חקיקה, הלכה פסוקה והיקש, מכריעים לאור עקרונות החירות, הצדק, היושר והשלום של המשפט העברי ומורשת ישראל'], 'c': 3, 'e': 'נכון. זה הנוסח לאחר תיקון 2018, כולל המילים ״המשפט העברי״.'}, {'q': 'מה היה השינוי שהכניס תיקון 2018 לחוק יסודות המשפט?', 'o': ['החליף את ״מורשת ישראל״ במשפט האנגלי', 'ביטל את החוק כולו', 'הפך את החוק לחוק יסוד', 'הוסיף במפורש את ״המשפט העברי״ להפניה, כך שהיא כעת לעקרונות ״של המשפט העברי ומורשת ישראל״'], 'c': 3, 'e': 'נכון. התיקון הוסיף את הביטוי ״המשפט העברי״, בלי לשנות את סדר המקורות.'}, {'q': 'מה סדר הפנייה למקורות לפי ס׳ 1 לחוק יסודות המשפט?', 'o': ['היקש ← הלכה ← חקיקה ← משפט עברי', 'משפט עברי ← חקיקה ← הלכה ← היקש', 'הלכה ← חקיקה ← משפט אנגלי ← היקש', 'חקיקה ← הלכה פסוקה ← היקש ← עקרונות החירות, הצדק, היושר והשלום של המשפט העברי ומורשת ישראל'], 'c': 3, 'e': 'נכון. זה הסדר המופיע בלשון הסעיף.'}, {'q': 'החוק שותק בעניין מסוים, אבל מדברי ההסבר ומההקשר עולה שהמחוקק בחר במכוון שלא להעניק זכות כזו. האם חל ס׳ 1 לחוק יסודות המשפט?', 'o': ['לא — כי חוק יסודות המשפט בוטל', 'כן — כל שתיקה היא לאקונה', 'לא — זהו הסדר שלילי, ולא לאקונה', 'כן — אבל רק בהסכמת היועץ המשפטי לממשלה'], 'c': 2, 'e': 'נכון. כשהשתיקה מכוונת התשובה היא ״לא״, ואין חסר שיש להשלים.'}, {'q': 'מה משמעות ס׳ 2(ב) לחוק יסודות המשפט?', 'o': ['שהמשפט האנגלי ממשיך לחול על כל שאלה חדשה', 'שדוקטרינות שנקלטו במשפט הישראלי לפני 1980 נשארות בתוקף, למרות ביטול סימן 46', 'שפסקי דין שניתנו לפני 1980 בטלים', 'שהחוקים העות׳מאניים בוטלו'], 'c': 1, 'e': 'נכון. הסעיף משמר את ״המשפט שנקלט בארץ״ לפני תחילת החוק.'}, {'q': 'דוקטרינה מדיני היושר האנגליים נקלטה בפסיקה הישראלית בשנות ה־60. צד טוען שמאז 1980 היא בטלה. מה הדין?', 'o': ['הטענה נכונה רק אם הדוקטרינה סותרת את המשפט העברי', 'הטענה נכונה — ביטול סימן 46 ביטל את כל המשפט האנגלי', 'הטענה שגויה — כי סימן 46 מעולם לא בוטל', 'הטענה שגויה — ס׳ 2(ב) לחוק יסודות המשפט שומר על המשפט שנקלט לפני תחילת החוק, ובית המשפט רשאי לפתח את הדוקטרינה כחלק מהמשפט הישראלי'], 'c': 3, 'e': 'נכון. מה שנקלט נשאר חלק מהשיטה, וממילא אינו מותנה עוד בשינויים במשפט האנגלי.'}, {'q': 'מדוע ביטול סימן 46 לא פגע בחוקים העות׳מאניים שעוד היו בתוקף ב־1980?', 'o': ['כי חוק יסודות המשפט מנה אותם אחד לאחד', 'כי מקור תחולתם אחרי 1948 הוא ס׳ 11 לפקודת סדרי השלטון והמשפט', 'כי הם חוקי יסוד', 'כי הם חלים רק בבתי הדין השרעיים'], 'c': 1, 'e': 'נכון. ס׳ 11 קלט את כל המשפט הקיים, ולכן ביטול סימן 46 לא נגע בתחולתם.'}, {'q': 'בפרשת הנדלס, מה הייתה עמדת השופט אלון?', 'o': ['שאין שום מקום למשפט העברי בפסיקה', 'שהמציאה שייכת למדינה', 'שהמשפט העברי הוא ״מקור השראה ראשי וראשון במעלה״, וניתן לפנות אליו גם בפירוש מונח שיש בו ספק', 'שיש לפנות למשפט האנגלי'], 'c': 2, 'e': 'נכון. אלון הרחיב את הפנייה למשפט העברי גם לספקות פרשניים — ונותר בדעת מיעוט.'}, {'q': 'מה הייתה התוצאה הקונקרטית בפרשת הנדלס?', 'o': ['איגרות החוב נמסרו למוצא', 'איגרות החוב חולקו בין המוצא לבנק', 'איגרות החוב הוחזרו לבעליהן שאותרו', 'איגרות החוב נמסרו לבנק, שבחדר הכספות שלו נמצאו'], 'c': 3, 'e': 'נכון. בערעור הכריע הרוב לטובת הבנק, והדיון הנוסף אישר זאת.'}, {'q': 'מה קבע השופט ברק בבג״ץ ז׳רז׳בסקי לגבי עקרונות מורשת ישראל?', 'o': ['שהם המקור היחיד שאליו יש לפנות בלאקונה וגם בפרשנות', 'שהם גוברים על חוקי הכנסת', 'שאין להם מעמד משפטי כלשהו', 'שהם חלק מעקרונות היסוד של השיטה, אך אינם המקור היחיד שאליו יש לפנות'], 'c': 3, 'e': 'נכון. זו עמדתו: מקור חשוב, חלק מעקרונות היסוד — אך לא בלעדי.'}, {'q': 'מה קבע בג״ץ קול העם לגבי מעמדה של הכרזת העצמאות?', 'o': ['שאינה חוקה, אך יש להתחשב בה בפירוש חוקי המדינה', 'שהיא מחייבת רק את הכנסת', 'שאין לה כל משמעות משפטית', 'שהיא חוקה שמכוחה ניתן לבטל חוקים'], 'c': 0, 'e': 'נכון. ההכרזה משמשת מקור פרשני, וממנה גזר בית המשפט את מעמדו של חופש הביטוי.'}, {'q': 'שופט שואל אם אמנה בינלאומית שישראל חתמה עליה ואשררה, אך הכנסת לא קלטה בחקיקה, מחייבת אותו כחלק מהדין הפנימי. מה התשובה העקרונית?', 'o': ['לא — אמנה מחייבת את המדינה במישור הבינלאומי, אך בדין הפנימי היא חלה רק אם נקלטה בחקיקה; המשפט הבינלאומי המנהגי, לעומת זאת, חל ישירות כל עוד אינו סותר חוק', 'כן — כל אמנה שאושררה היא חלק מהדין הפנימי', 'כן — אבל רק בבית המשפט העליון', 'לא — המשפט הבינלאומי אינו מקור משפט בישראל בשום מצב'], 'c': 0, 'e': 'נכון. זו ההבחנה בין משפט הסכמי למשפט מנהגי; עם זאת, חזקה פרשנית מעודדת לפרש חוקים בהתאם להתחייבויות הבינלאומיות.'}, {'q': 'סטודנט כתב: ״פקודת הנזיקין היא חקיקת משנה, כי חוקקה בידי הנציב העליון ולא בידי הכנסת״. מה הטעות?', 'o': ['אין טעות', 'פקודה מנדטורית היא חקיקה ראשית — לפי חוק הפרשנות ״חוק״ הוא חוק של הכנסת או פקודה', 'פקודת הנזיקין היא חוק יסוד', 'פקודת הנזיקין בוטלה ב־1948'], 'c': 1, 'e': 'נכון. ההגדרה בחוק הפרשנות משווה בין חוק של הכנסת לבין פקודה; ההבדל הוא רק במקור ההיסטורי.'}, {'q': 'לפי סעיף 20 לחוק יסוד: השפיטה, הלכת בית המשפט העליון:', 'o': ['מחייבת רק את העליון', 'מחייבת כל ערכאה נמוכה ממנו', 'אינה מחייבת אף ערכאה', 'מחייבת את הכנסת'], 'c': 1, 'e': 'הלכת העליון מחייבת ערכאות נמוכות; העליון עצמו אינו כבול לה.'}, {'q': 'מה קובע חוק יסודות המשפט, התש"ם-1980, במצב של לקונה?', 'o': ['לפנות למשפט האנגלי', 'לפנות לעקרונות מורשת ישראל', 'לפסול את התביעה', 'להעביר לכנסת'], 'c': 1, 'e': 'החוק ביטל את ההפניה למשפט האנגלי והפנה לעקרונות החירות, הצדק, היושר והשלום של מורשת ישראל.'}]
